def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    token_counts = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or not token.isascii() or not token.isdigit():
            return None

        # Small chunks also support amounts beyond Python's string-to-int limit.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split()
        if not tokens or token_counts.get(tokens[0]) != len(tokens):
            rejected.append(index)
            continue

        verb = tokens[0]

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(tokens[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = tokens[1]

        if verb == "open":
            if name in accounts:
                rejected.append(index)
                continue
            history.append(((name, None),))
            accounts[name] = (amount, False)
            continue

        if name not in accounts:
            rejected.append(index)
            continue

        previous = accounts[name]
        balance, frozen = previous

        if verb == "deposit":
            accounts[name] = (balance + amount, frozen)

        elif verb == "withdraw":
            if frozen or balance < amount:
                rejected.append(index)
                continue
            accounts[name] = (balance - amount, frozen)

        elif verb == "transfer":
            destination = tokens[2]
            if (
                destination == name
                or destination not in accounts
                or frozen
                or balance < amount
            ):
                rejected.append(index)
                continue

            destination_previous = accounts[destination]
            destination_balance, destination_frozen = destination_previous
            history.append(
                ((name, previous), (destination, destination_previous))
            )
            accounts[name] = (balance - amount, frozen)
            accounts[destination] = (
                destination_balance + amount,
                destination_frozen,
            )
            continue

        elif verb == "freeze":
            if frozen:
                rejected.append(index)
                continue
            accounts[name] = (balance, True)

        elif verb == "unfreeze":
            if not frozen:
                rejected.append(index)
                continue
            accounts[name] = (balance, False)

        history.append(((name, previous),))

    return {name: state[0] for name, state in accounts.items()}, rejected
